let adminTab='users',calendarMode='team',calendarPending=false,requestStatus='all',requestType='all',adminPeopleQuery='';
const roleKey=r=>({admin:'adminRole',manager:'managerRole',employee:'employeeRole'}[r]||'employeeRole');
function actorId(){return state?.demoActor||'me'}
function canAdmin(){return person(actorId()).role==='admin'}
function canManage(){return ['admin','manager'].includes(person(actorId()).role)}
function activePeople(){return state.people.filter(p=>p.active!==false)}
function visibleChannels(){return state.channels.filter(c=>c.kind==='group'&&!c.private||c.members.includes(actorId()))}
function companyClosure(date){return (state.holidays||[]).find(h=>h.active!==false&&h.start<=date&&h.end>=date)}
function isWorkingDate(date){const day=toDate(date).getDay();return day!==0&&day!==6&&!companyClosure(date)}
function memberLabel(n){if(lang==='en')return `${n} ${n===1?'member':'members'}`;const category=new Intl.PluralRules('uk').select(n);return `${n} ${category==='one'?'учасник':category==='few'?'учасники':'учасників'}`}
function personaControl(){return `<label class="persona-control"><span>${esc(t('adminDemo'))}</span><select id="demo-actor" aria-label="${esc(t('adminDemo'))}">${activePeople().map(p=>`<option value="${p.id}" ${p.id===actorId()?'selected':''}>${esc(p.name)} · ${esc(t(roleKey(p.role)))}</option>`).join('')}</select></label>`}
/* Anniversaries are auto-scheduled in the local demo only, not a KEL policy. */
function syncAnniversaryDemoBonus(p){
 const day=p.anniversary||'';
 const valid=p.active!==false&&validDate(day);
 const year=valid?Number(day.slice(0,4)):null;
 const grantId=year===null?'':`anniversary-demo-${p.id}-${year}`;
 const bookingId=year===null?'':`anniversary-demo-booking-${p.id}-${year}`;
 const obsolete=state.bonuses.filter(g=>g.autoAnniversaryDemo===true&&g.person===p.id&&g.id!==grantId);
 const obsoleteIds=new Set(obsolete.map(g=>g.id));
 if(obsoleteIds.size){
  state.bonuses=state.bonuses.filter(g=>!obsoleteIds.has(g.id));
  state.requests=state.requests.filter(r=>!obsoleteIds.has(r.grantId)||r.autoAnniversaryDemo!==true);
 }
 if(!valid)return 'none';
 const manual=state.bonuses.find(g=>g.person===p.id&&g.year===year&&g.reason==='anniversary'&&g.autoAnniversaryDemo!==true&&g.active!==false);
 if(manual)return 'manual';
 let grant=state.bonuses.find(g=>g.id===grantId);
 if(!grant){
  grant={id:grantId,person:p.id,reason:'anniversary',year,days:1,expiry:'',active:true,
   created:TODAY,createdBy:'demo',autoAnniversaryDemo:true};
  state.bonuses.push(grant);
 }
 const booked=state.requests.find(r=>r.id===bookingId);
 if(grant.active===false)return 'revoked';
 if(booked?.status==='cancelled')return 'cancelled';
 const requested={id:bookingId,person:p.id,type:'bonus',grantId:grant.id,start:day,end:day,
  status:'approved',note:'DEMO ONLY — automatically scheduled anniversary bonus; not an approved company policy.',
  created:TODAY,autoAnniversaryDemo:true};
 if(!isWorkingDate(day)||overlaps(requested,bookingId)){
  if(booked?.autoAnniversaryDemo===true)state.requests=state.requests.filter(r=>r.id!==bookingId);
  return 'unscheduled';
 }
 if(booked?.autoAnniversaryDemo===true)Object.assign(booked,requested);
 else if(!booked)state.requests.push(requested);
 return 'scheduled';
}
function initializeHR(){
 for(const p of state.people){p.role??=p.id==='darren'?'admin':p.id==='david'?'manager':'employee';p.active??=true;p.email??=`${p.id==='me'?'bohdan.demo':p.name.toLowerCase().replace(/[^a-z]+/g,'.')}@example.com`;p.allowances??={vacation:20,sick:7,personal:30};}
 state.settings??={hoursPerDay:8};state.holidays??=[];state.bonuses??=[];state.audit??=[];state.demoActor??='darren';
 if(!activePeople().some(p=>p.id===actorId()))state.demoActor='me';
 if(!state.hrVersion){
  state.holidays.push({id:'sample-closure',nameKey:'sampleHoliday',title:'Company day off · sample',start:nextWork(TODAY,12),end:nextWork(TODAY,12),active:true,createdBy:'me'});
  state.bonuses.push({id:'sample-bonus-me',person:'me',reason:'ownerGift',year:Number(TODAY.slice(0,4)),days:1,created:TODAY,createdBy:'me',expiry:'',active:true});
  state.hrVersion=3;
 }
 for(const p of state.people)syncAnniversaryDemoBonus(p);
 persist();
}
function audit(kind,detail){state.audit.push({id:uid(),kind,detail,actor:actorId(),at:new Date().toISOString()})}
function leaveHours(r,year){const a=year?`${year}-01-01`:r.start,b=year?`${year}-12-31`:r.end;const s=r.start>a?r.start:a,e=r.end<b?r.end:b;if(s>e)return 0;const days=workDays(s,e);return r.unit==='hours'?(days?Number(r.hours)||0:0):days*state.settings.hoursPerDay}
function leaveDays(r,year){return leaveHours(r,year)/state.settings.hoursPerDay}
function amount(r,year){return r.type==='personal'?leaveHours(r,year):leaveDays(r,year)}
const number=n=>Number(n.toFixed(2)).toLocaleString(locale());
function duration(r,year){return `${number(amount(r,year))} ${t(r.type==='personal'?'hours':'days')}`}
function allowance(p,type){return Number(person(p).allowances?.[type])||0}
function usedAllowance(p,type,year=Number(TODAY.slice(0,4)),exclude=''){return state.requests.filter(r=>r.id!==exclude&&r.person===p&&r.type===type&&r.status==='approved').reduce((n,r)=>n+amount(r,year),0)}
function availableAllowance(p,type,year,exclude=''){return allowance(p,type)-usedAllowance(p,type,year,exclude)}
function grantBookings(g,excluded=''){return state.requests.filter(r=>r.id!==excluded&&r.grantId===g.id&&['pending','approved'].includes(r.status)&&leaveDays(r)>0)}
function grantStatus(g,date=TODAY){if(g.active===false)return 'bonusRevoked';const book=grantBookings(g);if(book.some(r=>r.status==='approved'))return 'bonusUsed';if(book.some(r=>r.status==='pending'))return 'bonusReserved';if(g.expiry&&g.expiry<date)return 'bonusExpired';return 'bonusAvailable'}
function availableGrants(p,date=TODAY,exclude=''){return state.bonuses.filter(g=>g.person===p&&g.active!==false&&(!g.expiry||g.expiry>=date)&&!grantBookings(g,exclude).length)}
function overlaps(r,exclude=''){
 return state.requests.some(x=>{if(x.id===exclude||x.person!==r.person||!['pending','approved'].includes(x.status)||x.start>r.end||x.end<r.start)return false;if(r.unit==='hours'&&x.unit==='hours'&&r.start===x.start)return r.startTime<x.endTime&&r.endTime>x.startTime;const s=x.start>r.start?x.start:r.start,e=x.end<r.end?x.end:r.end;return workDays(s,e)>0});
}
function budgetCards(p=actorId()){
 const year=Number(TODAY.slice(0,4));return `<div class="hr-balances">${[['vacation','sun'],['sick','heart'],['personal','clock']].map(([type,ico])=>{const total=allowance(p,type),used=usedAllowance(p,type,year),remaining=total-used;return `<section class="balance-card"><div class="label">${icon(ico)}${esc(t(type))}</div><div class="balance-number ${remaining<0?'over-budget':''}">${number(remaining)} <span>/ ${number(total)} ${esc(t(type==='personal'?'hours':'days'))}</span></div><div class="balance-bar"><span style="width:${total?Math.max(0,Math.min(100,remaining/total*100)):0}%"></span></div><small>${number(used)} ${esc(t('used'))} · ${year}</small></section>`}).join('')}<section class="balance-card bonus-balance"><div class="label">${icon('gift')}${esc(t('bonusBalance'))}</div><div class="balance-number">${availableGrants(p).length} <span>${esc(t('days'))}</span></div><small>${esc(t('bonusSeparate'))}</small>${p===actorId()?btn(t('bookBonus'),'request-bonus','text-button','arrow'):''}</section></div>`;
}
function demoHRNote(){return `<div class="demo-callout">${icon('shield')}<p>${esc(t('hrLocal'))}</p></div>`}
function adminTabs(){return `<div class="tabs admin-tabs">${(canAdmin()?['users','requests','holidays','bonus','settings','history']:['requests','history']).map(tab=>`<button class="tab ${adminTab===tab?'active':''}" data-action="admin-tab" data-tab="${tab}">${esc(t({users:'adminUsers',requests:'adminRequests',holidays:'adminHolidays',bonus:'adminBonus',settings:'adminSettings',history:'adminHistory'}[tab]))}${tab==='requests'?`<span class="badge">${state.requests.filter(r=>r.status==='pending').length}</span>`:''}</button>`).join('')}</div>`}
function renderAdmin(){
 if(!canManage())return '';
 if(!canAdmin()&&!['requests','history'].includes(adminTab))adminTab='requests';
 const action=canAdmin()?({users:btn(t('addUser'),'add-user','primary','plus'),holidays:btn(t('addHoliday'),'add-holiday','primary','plus'),bonus:btn(t('grantBonus'),'grant-bonus','primary','gift')}[adminTab]||''):'';
 return `${pageHeading('PEOPLE OPERATIONS',t('admin'),t('adminSub'),action)}<div class="admin-summary"><span>${icon('people')}<b>${activePeople().length}</b>${esc(t('active'))}</span><span>${icon('clock')}<b>${state.requests.filter(r=>r.status==='pending').length}</b>${esc(t('pending'))}</span><span class="green-summary">${icon('gift')}<b>${state.bonuses.filter(g=>grantStatus(g)==='bonusAvailable').length}</b>${esc(t('availableBonus'))}</span></div><section class="card">${adminTabs()}<div class="admin-content">${adminTab==='users'?adminUsers():adminTab==='requests'?requestList(true):adminTab==='holidays'?adminHolidays():adminTab==='bonus'?adminBonuses():adminTab==='settings'?adminSettings():adminHistory()}</div></section>${demoHRNote()}`;
}
function adminUsers(){return `<div class="admin-toolbar"><div class="input-search">${icon('search')}<input id="admin-people-search" type="search" value="${esc(adminPeopleQuery)}" placeholder="${esc(t('searchPeople'))}" aria-label="${esc(t('searchPeople'))}"></div><span class="muted">${esc(t('emailPrivate'))}</span></div><div id="admin-users-table">${userRows()}</div><div class="section-footer">${icon('info')}${esc(t('profileOnly'))}</div>`}
function userRows(){const ps=state.people.filter(p=>`${p.name} ${p.email}`.toLowerCase().includes(adminPeopleQuery.toLowerCase()));return `<div class="table-wrap"><table class="data-table users-table"><thead><tr>${['employee','workEmail','userRole','status','actions'].map(k=>`<th scope="col">${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${ps.map(p=>`<tr><td><div class="table-person">${av(p,'sm')}<div><b>${esc(p.name)}</b><small>${esc(t(p.dept))} · ${esc(p.job)}</small></div></div></td><td class="email-cell">${esc(p.email)}</td><td><span class="role-tag ${p.role}">${esc(t(roleKey(p.role)))}</span></td><td><span class="tag ${p.active?'':'cancelled'}">${esc(t(p.active?'active':'inactive'))}</span></td><td><div class="request-actions">${btn(t('edit'),'edit-user','small-btn','edit',`data-id="${p.id}"`)}${btn(t(p.active?'deactivate':'reactivate'),'toggle-user','small-btn '+(p.active?'danger':''),'',`data-id="${p.id}"`)}</div></td></tr>`).join('')}</tbody></table></div>`}
function adminHolidays(){const hs=state.holidays.slice().sort((a,b)=>a.start.localeCompare(b.start));return `<p class="admin-description">${esc(t('closureNote'))}</p>${hs.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${['holidayTitle','dates','status','actions'].map(k=>`<th>${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${hs.map(h=>`<tr><td><div class="table-person"><span class="closure-symbol">${icon('calendar')}</span><b>${esc(h.nameKey?t(h.nameKey):h.title)}</b></div></td><td>${esc(range(h.start,h.end))}</td><td><span class="tag ${h.active?'':'cancelled'}">${esc(t(h.active?'active':'cancelled'))}</span></td><td><div class="request-actions">${btn(t('edit'),'edit-holiday','small-btn','edit',`data-id="${h.id}"`)}${btn(t(h.active?'archiveHoliday':'restoreHoliday'),'toggle-holiday','small-btn danger','',`data-id="${h.id}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:empty(icon('calendar'),t('holidayEmpty'),'')}<div class="section-footer">${icon('info')}${esc(t('holidayRule'))}</div>`}
function adminBonuses(){const gs=state.bonuses.slice().reverse();return `<div class="bonus-explainer">${icon('gift')}<div><strong>${esc(t('fromOwner'))}</strong><p>${esc(t('bonusNote'))}</p></div></div>${gs.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${['employee','bonusReason','grant','status','actions'].map(k=>`<th>${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${gs.map(g=>{const status=grantStatus(g),book=grantBookings(g)[0];return `<tr><td><div class="table-person">${av(person(g.person),'sm')}<b>${esc(person(g.person).name)}</b></div></td><td>${esc(t(g.reason))}<small class="cell-sub">${g.year} · ${esc(g.expiry?fmt(g.expiry):t('noExpiry'))}</small></td><td><span class="bonus-value">${icon('gift')} +1 ${esc(t('days'))}</span></td><td><span class="tag ${status==='bonusAvailable'?'gift-tag':status==='bonusReserved'?'pending':status==='bonusUsed'?'blue':'cancelled'}">${esc(t(status))}</span>${book?`<small class="cell-sub">${esc(range(book.start,book.end))}</small>`:''}</td><td>${btn(t(g.active===false?'restoreBonus':'revokeBonus'),'toggle-bonus','small-btn '+(g.active===false?'':'danger'),'',`data-id="${g.id}"`)}</td></tr>`}).join('')}</tbody></table></div>`:empty(icon('gift'),t('bonusEmpty'),'')}`}
function adminSettings(){return `<form id="settings-form" class="settings-form"><h3>${esc(t('companyPolicy'))}</h3><p class="modal-subtitle">${esc(t('settingsNote'))}</p><label class="field"><span>${esc(t('hoursPerDay'))}</span><input type="number" name="hoursPerDay" min="1" max="24" step="0.25" required value="${state.settings.hoursPerDay}"><small>${esc(t('weekdaysNote'))}</small></label><p class="modal-subtitle">${esc(t('personSettings'))}: ${esc(t('notPolicy'))}</p><div class="outlook-card">${icon('calendar')}<div><strong>Microsoft Outlook</strong><p>${esc(t('outlookNote'))}</p></div></div><p class="form-error" id="settings-error" role="alert"></p><button class="primary" type="submit">${esc(t('saveSettings'))}</button></form>`}
function adminHistory(){const entries=canAdmin()?state.audit:state.audit.filter(a=>['auditRequest','auditDecision'].includes(a.kind));return entries.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${esc(t('auditWhen'))}</th><th>${esc(t('auditActor'))}</th><th>${esc(t('auditAction'))}</th></tr></thead><tbody>${entries.slice().reverse().map(a=>`<tr><td>${esc(new Date(a.at).toLocaleString(locale(),{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))}</td><td>${esc(person(a.actor).name)}</td><td><b>${esc(t(a.kind))}</b><small class="cell-sub">${esc(a.detail)}</small></td></tr>`).join('')}</tbody></table></div>`:empty(icon('clock'),t('noAudit'),'')}

function userForm(id){if(!canAdmin())return;const p=id?person(id):{name:'',email:'',job:'',dept:'warehouse',role:'employee',active:true,birthday:'',anniversary:'',allowances:{vacation:20,sick:7,personal:30}};
 showModal(t(id?'editUser':'addUser'),`<p class="modal-subtitle">${esc(t('profileOnly'))}</p><input type="hidden" name="id" value="${esc(id||'')}"><label class="field"><span>${esc(t('fullName'))}</span><input name="fullName" required maxlength="70" value="${esc(p.name)}" autocomplete="off"></label><label class="field"><span>${esc(t('workEmail'))}</span><input name="email" type="email" required maxlength="140" value="${esc(p.email)}" placeholder="name@company.com" autocomplete="off"></label><div class="field-row"><label class="field"><span>${esc(t('department'))}</span><select name="dept">${['warehouse','projects','office'].map(d=>`<option value="${d}" ${p.dept===d?'selected':''}>${esc(t(d))}</option>`).join('')}</select></label><label class="field"><span>${esc(t('userRole'))}</span><select name="role">${['employee','manager','admin'].map(r=>`<option value="${r}" ${p.role===r?'selected':''}>${esc(t(roleKey(r)))}</option>`).join('')}</select></label></div><label class="field"><span>${esc(t('jobTitle'))}</span><input name="job" maxlength="70" value="${esc(p.job)}"></label><div class="form-section-label">${esc(t('allowanceTitle'))}</div><div class="allowance-fields">${['vacation','sick','personal'].map(k=>`<label class="field"><span>${esc(t(k))} (${esc(t(k==='personal'?'hours':'days'))})</span><input name="${k}" type="number" min="0" max="500" step="0.25" required value="${p.allowances[k]}"></label>`).join('')}</div><div class="field-row"><label class="field"><span>${esc(t('birthdayDate'))}</span><input name="birthday" type="text" inputmode="numeric" placeholder="MM-DD" pattern="[0-9]{2}-[0-9]{2}" value="${esc(p.birthday||'')}"><small>${esc(t('birthdayHelp'))}</small></label><label class="field"><span>${esc(t('anniversaryDate'))}</span><input name="anniversary" type="date" value="${esc(p.anniversary||'')}"></label></div><small class="muted">${esc(t('anniversaryDemoNote'))}</small><label class="switch-field"><input name="active" type="checkbox" ${p.active?'checked':''}>${esc(t('activeUser'))}</label><p class="form-error" id="form-error" role="alert"></p>`,modalActions(t('saveUser')),'user-form');
}
function submitUser(form){if(!canAdmin())return;const d=new FormData(form),id=String(d.get('id')),old=id?person(id):null;const name=String(d.get('fullName')).trim(),email=String(d.get('email')).trim().toLowerCase(),role=d.get('role'),active=d.has('active');const err=$('#form-error');const limits=Object.fromEntries(['vacation','sick','personal'].map(k=>[k,Number(d.get(k))]));
 if(!name||!/^\S+@[^\s@]+\.[^\s@]+$/.test(email)||!['employee','manager','admin'].includes(role)||Object.values(limits).some(x=>!Number.isFinite(x)||x<0||x>500)){err.textContent=t('invalidUser');return}
 if(state.people.some(p=>p.id!==id&&p.email.toLowerCase()===email)){err.textContent=t('duplicateEmail');return}
 if(id===actorId()&&!active){err.textContent=t('selfDeactivate');return}
 if(old?.role==='admin'&&old.active&&(role!=='admin'||!active)&&!state.people.some(p=>p.id!==id&&p.role==='admin'&&p.active)){err.textContent=t('lastAdmin');return}
 const birthday=String(d.get('birthday')||'');if(birthday&&!validDate('2000-'+birthday)){err.textContent=t('invalidUser');return}
 const anniversary=String(d.get('anniversary')||'');if(anniversary&&!validDate(anniversary)){err.textContent=t('invalidUser');return}
 const patch={name:name.slice(0,70),email,job:String(d.get('job')).trim().slice(0,70),dept:d.get('dept'),role,active,birthday,anniversary,allowances:limits,initials:name.split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase()};
 if(old)Object.assign(old,patch);else{const p={...patch,id:uid(),color:'#e2ecde',ink:'#5e8153'};state.people.push(p);for(const c of state.channels.filter(c=>c.kind==='group'&&!c.private))c.members.push(p.id)}
 const anniversaryResult=syncAnniversaryDemoBonus(old||state.people.at(-1));
 audit('auditUser',`${name} · ${email}`);persist();closeModal();render();toast(t('userSaved')+(anniversaryResult==='scheduled'?' '+t('anniversaryScheduled'):anniversaryResult==='unscheduled'?' '+t('anniversaryUnscheduled'):''));
}
function toggleUser(id){if(!canAdmin())return;const p=person(id);if(p.id===actorId()&&p.active){toast(t('selfDeactivate'));return}if(p.active&&p.role==='admin'&&!state.people.some(x=>x.id!==id&&x.active&&x.role==='admin')){toast(t('lastAdmin'));return}p.active=!p.active;audit('auditUser',`${p.name} · ${p.active?'active':'inactive'}`);persist();render()}
function holidayForm(id){if(!canAdmin())return;const h=id?state.holidays.find(h=>h.id===id):{title:'',start:nextWork(TODAY,5),end:nextWork(TODAY,5)};showModal(t(id?'editHoliday':'addHoliday'),`<p class="modal-subtitle">${esc(t('closureNote'))}</p><input type="hidden" name="id" value="${esc(id||'')}"><label class="field"><span>${esc(t('holidayTitle'))}</span><input name="title" required maxlength="90" placeholder="${esc(t('holidayPlaceholder'))}" value="${esc(h.nameKey?t(h.nameKey):h.title)}"></label><div class="field-row"><label class="field"><span>${esc(t('from'))}</span><input type="date" name="start" required value="${h.start}"></label><label class="field"><span>${esc(t('to'))}</span><input type="date" name="end" required value="${h.end}"></label></div><div class="request-summary">${icon('calendar')}<span>${esc(t('holidayRecount'))}</span></div><p class="form-error" id="form-error" role="alert"></p>`,modalActions(t('save')),'holiday-form')}
function submitHoliday(form){if(!canAdmin())return;const d=new FormData(form),id=String(d.get('id')),title=String(d.get('title')).trim(),start=d.get('start'),end=d.get('end');const err=$('#form-error');if(!title||!validRange(start,end)){err.textContent=t('validDates');return}if(state.holidays.some(h=>h.id!==id&&h.active!==false&&h.start<=end&&h.end>=start)){err.textContent=t('holidayConflict');return}const h=state.holidays.find(h=>h.id===id);if(h){const old={...h};Object.assign(h,{title,nameKey:null,start,end});if(state.bonuses.some(g=>grantBookings(g).length>1)){Object.assign(h,old);err.textContent=t('holidayBonusConflict');return}}else state.holidays.push({id:uid(),title,start,end,active:true,createdBy:actorId()});audit('auditClosure',`${title} · ${start} → ${end}`);persist();closeModal();render();toast(t('holidaySaved'))}
function validRange(start,end){return validDate(start)&&validDate(end)&&end>=start&&(toDate(end)-toDate(start))/86400000<=365}
function toggleHoliday(id){if(!canAdmin())return;const h=state.holidays.find(h=>h.id===id);if(!h)return;if(h.active===false&&state.holidays.some(x=>x.id!==id&&x.active!==false&&x.start<=h.end&&x.end>=h.start)){toast(t('holidayRestoreConflict'));return}h.active=h.active===false;if(state.bonuses.some(g=>grantBookings(g).length>1)){h.active=!h.active;toast(t('holidayBonusConflict'));return}audit('auditClosure',`${h.title} · ${h.active?'active':'cancelled'}`);persist();render();toast(t('holidayChanged'))}
function grantForm(){if(!canAdmin())return;const date=nextWork(TODAY,6);showModal(t('grantBonus'),`<p class="modal-subtitle">${esc(t('bonusNote'))}</p><label class="field"><span>${esc(t('employee'))}</span><select name="person">${activePeople().map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><div class="field-row"><label class="field"><span>${esc(t('bonusReason'))}</span><select name="reason">${['birthday','anniversary','ownerGift'].map(r=>`<option value="${r}">${esc(t(r))}</option>`).join('')}</select></label><label class="field"><span>${esc(t('bonusYear'))}</span><input name="year" type="number" min="2020" max="2100" required value="${TODAY.slice(0,4)}"></label></div><label class="field"><span>${esc(t('bonusExpiry'))}</span><input name="expiry" type="date"></label><label class="switch-field"><input name="schedule" id="schedule-bonus" type="checkbox">${esc(t('scheduleBonus'))}</label><label class="field" id="bonus-date-field" hidden><span>${esc(t('bonusDate'))}</span><input name="date" type="date" value="${date}"></label><div class="request-summary bonus-request-summary">${icon('gift')}<span><b>+1 ${esc(t('days'))}</b> · ${esc(t('bonusSeparate'))}</span></div><p class="form-error" id="form-error" role="alert"></p>`,modalActions(t('grantBonus')),'bonus-form');$('#schedule-bonus').addEventListener('change',e=>{$('#bonus-date-field').hidden=!e.target.checked})}
function submitGrant(form){if(!canAdmin())return;const d=new FormData(form),personId=d.get('person'),reason=d.get('reason'),year=Number(d.get('year')),expiry=String(d.get('expiry')||''),date=d.get('date'),schedule=d.has('schedule');const err=$('#form-error');if(!activePeople().some(p=>p.id===personId)||!['birthday','anniversary','ownerGift'].includes(reason)||year<2020||year>2100||!Number.isInteger(year)||expiry&&!validDate(expiry)){err.textContent=t('validDates');return}if(reason!=='ownerGift'&&state.bonuses.some(g=>g.person===personId&&g.reason===reason&&g.year===year&&g.active!==false)){err.textContent=t('bonusDuplicate');return}const req={id:uid(),person:personId,type:'bonus',start:date,end:date,status:'approved',note:'',created:TODAY,decidedBy:actorId(),decidedAt:new Date().toISOString()};if(schedule&&(!validDate(date)||!isWorkingDate(date)||expiry&&date>expiry||overlaps(req))){err.textContent=t('bonusNoWork');return}const g={id:uid(),person:personId,reason,year,days:1,expiry,active:true,created:TODAY,createdBy:actorId()};state.bonuses.push(g);if(schedule){req.grantId=g.id;state.requests.push(req)}audit('auditBonus',`${person(personId).name} · ${t(reason)} · +1`);persist();closeModal();render();toast(t('bonusSaved'))}
function toggleBonus(id){if(!canAdmin())return;const g=state.bonuses.find(g=>g.id===id);if(!g)return;if(grantBookings(g).length){toast(t('bonusInUse'));return}if(g.active===false&&g.reason!=='ownerGift'&&state.bonuses.some(x=>x.id!==id&&x.person===g.person&&x.reason===g.reason&&x.year===g.year&&x.active!==false)){toast(t('bonusDuplicate'));return}g.active=g.active===false;audit('auditBonusState',`${person(g.person).name} · ${g.active?'active':'revoked'}`);persist();render()}

renderTimeoff=function(){
 if(!canManage()&&requestTab==='review')requestTab='mine';
 return `${pageHeading('TIME FOR LIFE',t('timeoff'),t('timeoffSub'),btn(t('request'),'request','primary','plus'))}${budgetCards()}<section class="card"><div class="tabs"><button class="tab ${requestTab==='mine'?'active':''}" data-action="request-tab" data-tab="mine">${esc(t('myRequests'))}</button>${canManage()?`<button class="tab ${requestTab==='review'?'active':''}" data-action="request-tab" data-tab="review">${esc(t('approvals'))}<span class="badge">${state.requests.filter(r=>r.status==='pending'&&r.person!==actorId()).length}</span></button>`:''}</div>${requestList(requestTab==='review')}</section><div class="demo-callout">${icon('info')}<p>${esc(t('notPolicy'))} ${esc(t('netDays'))}</p></div>`;
};
function requestList(review){
 const rs=state.requests.filter(r=>(review||r.person===actorId())&&(requestStatus==='all'||r.status===requestStatus)&&(requestType==='all'||r.type===requestType)).slice().reverse();
 return `${review?`<div class="review-hint">${esc(t('reviewHint'))}</div>`:''}<div class="admin-toolbar request-filters"><select class="filter-select" id="request-status" aria-label="${esc(t('allStatuses'))}">${['all','pending','approved','rejected','cancelled'].map(s=>`<option value="${s}" ${requestStatus===s?'selected':''}>${esc(t(s==='all'?'allStatuses':s))}</option>`).join('')}</select><select class="filter-select" id="request-type" aria-label="${esc(t('allTypes'))}">${['all','vacation','sick','personal','bonus'].map(s=>`<option value="${s}" ${requestType===s?'selected':''}>${esc(t(s==='all'?'allTypes':s))}</option>`).join('')}</select><span class="muted">${esc(t('netDays'))}</span></div>${rs.length?`<div class="table-wrap"><table class="data-table requests-table"><thead><tr>${[review?'employee':null,'type','dates','duration','status','actions'].filter(Boolean).map(k=>`<th scope="col">${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>{const p=person(r.person);return `<tr>${review?`<td><div class="table-person">${av(p,'sm')}<div><b>${esc(p.name)}</b><small>${esc(t(p.dept))}</small></div></div></td>`:''}<td><button class="request-type-link ${r.type}" data-action="request-detail" data-id="${r.id}">${icon(typeIcon(r.type))}${esc(t(r.type))}</button></td><td>${esc(range(r.start,r.end))}${r.unit==='hours'?`<small class="cell-sub">${esc(r.startTime)}–${esc(r.endTime)}</small>`:''}</td><td>${esc(duration(r))}</td><td><span class="tag ${r.status}">${esc(t(r.status))}</span>${r.decidedBy?`<small class="cell-sub">${esc(person(r.decidedBy).name)}</small>`:''}</td><td><div class="request-actions">${review&&r.status==='pending'&&r.person!==actorId()?`${btn(t('approve'),'approve','small-btn','check',`data-id="${r.id}"`)}${btn(t('reject'),'reject','small-btn danger','x',`data-id="${r.id}"`)}`:['pending','approved'].includes(r.status)&&(r.person===actorId()||canAdmin())?btn(t('withdraw'),'withdraw','small-btn danger','',`data-id="${r.id}"`):'<span class="muted">—</span>'}</div></td></tr>`}).join('')}</tbody></table></div>`:empty(icon('sun'),t('noMatchingRequests'),'')}`;
}
function typeIcon(type){return {vacation:'sun',sick:'heart',personal:'clock',bonus:'gift'}[type]||'calendar'}
requestModal=function(preselect='vacation'){
 const start=nextWork(TODAY,3);showModal(t('newRequest'),`<p class="modal-subtitle">${esc(t('requestSubtitle'))}</p><label class="field"><span>${esc(t('type'))}</span><select name="type" id="leave-type">${['vacation','sick','personal','bonus'].map(x=>`<option value="${x}" ${preselect===x?'selected':''}>${esc(t(x))}</option>`).join('')}</select></label><div id="bonus-picker" ${preselect==='bonus'?'':'hidden'}><label class="field"><span>${esc(t('bonusSelect'))}</span><select name="grantId" id="request-grant">${availableGrants(actorId(),start).map(g=>`<option value="${g.id}">${esc(t(g.reason))} · ${g.year} · +1 ${esc(t('days'))}</option>`).join('')}</select><small>${esc(t('bonusSeparate'))}</small></label></div><label class="field" id="unit-field" hidden><span>${esc(t('requestUnit'))}</span><select name="unit"><option value="hours">${esc(t('hourly'))}</option><option value="days">${esc(t('fullDays'))}</option></select></label><div class="field-row"><label class="field"><span>${esc(t('from'))}</span><input name="start" type="date" required value="${start}" min="${TODAY}" max="${addDays(TODAY,365)}"></label><label class="field" id="end-date-field"><span>${esc(t('to'))}</span><input name="end" type="date" required value="${start}" min="${start}" max="${addDays(TODAY,365)}"></label></div><div class="field-row" id="hour-fields" hidden><label class="field"><span>${esc(t('startTime'))}</span><input type="time" name="startTime" value="09:00" step="900"></label><label class="field"><span>${esc(t('endTime'))}</span><input type="time" name="endTime" value="11:00" step="900"></label></div><label class="field"><span>${esc(t('note'))}</span><textarea name="note" maxlength="300" placeholder="${esc(t('notePlaceholder'))}"></textarea><small>${esc(t('noteHint'))}</small></label><div class="request-summary" id="request-summary"></div><p class="form-error" id="form-error" role="alert"></p>`,modalActions(t('submitRequest')),'leave-form');
 const form=$('#leave-form');form.addEventListener('change',()=>refreshRequest(form));form.addEventListener('input',()=>refreshRequest(form));refreshRequest(form);
};
function requestFromForm(form){const d=new FormData(form),type=d.get('type'),hourly=type==='personal'&&d.get('unit')==='hours',start=d.get('start'),end=hourly||type==='bonus'?start:d.get('end');const startTime=d.get('startTime'),endTime=d.get('endTime');const minutes=s=>{if(!/^\d\d:\d\d$/.test(s))return NaN;const [h,m]=s.split(':').map(Number);return h*60+m};return {id:uid(),person:actorId(),type,unit:hourly?'hours':'days',start,end,startTime:hourly?startTime:'',endTime:hourly?endTime:'',hours:hourly?(minutes(endTime)-minutes(startTime))/60:undefined,note:String(d.get('note')||'').trim().slice(0,300),grantId:type==='bonus'?d.get('grantId'):undefined,status:'pending',created:TODAY}}
function refreshRequest(form){const type=form.elements.type.value,hourly=type==='personal'&&form.elements.unit.value==='hours',date=form.elements.start.value;$('#unit-field').hidden=type!=='personal';$('#hour-fields').hidden=!hourly;$('#end-date-field').hidden=hourly||type==='bonus';form.elements.end.required=!hourly&&type!=='bonus';form.elements.start.min=['vacation','bonus'].includes(type)?TODAY:addDays(TODAY,-30);if(form.elements.end.value<date)form.elements.end.value=date;form.elements.end.min=date;$('#bonus-picker').hidden=type!=='bonus';const current=form.elements.grantId.value;form.elements.grantId.innerHTML=availableGrants(actorId(),date||TODAY).map(g=>`<option value="${g.id}" ${current===g.id?'selected':''}>${esc(t(g.reason))} · ${g.year} · +1 ${esc(t('days'))}</option>`).join('');const r=requestFromForm(form);$('#request-summary').classList.toggle('bonus-request-summary',type==='bonus');$('#request-summary').innerHTML=`${icon(typeIcon(type))}<span><b>${esc(t('charge'))}: ${esc(duration(r))}</b><br>${esc(type==='bonus'?t('bonusSeparate'):t('netDays'))}</span>`}
function validateRequest(r,exclude=''){
 if(!['vacation','sick','personal','bonus'].includes(r.type)||!validRange(r.start,r.end)||r.end>addDays(TODAY,365))return t('validDates');
 if(['vacation','bonus'].includes(r.type)&&r.start<TODAY)return t('pastRequest');
 if(r.unit==='hours'&&(!Number.isFinite(r.hours)||r.hours<=0||r.hours>state.settings.hoursPerDay||r.start!==r.end))return t('badHours');
 if(workDays(r.start,r.end)===0)return t('notWorking');
 if(overlaps(r,exclude))return t('overlap');
 if(r.type==='bonus'){if(r.start!==r.end||leaveDays(r)!==1)return t('bonusOneDay');if(!availableGrants(r.person,r.end,exclude).some(g=>g.id===r.grantId))return t('noBonus')}
 return '';
}
submitRequest=function(form){const r=requestFromForm(form),error=validateRequest(r);if(error){$('#form-error').textContent=error;return}state.requests.push(r);audit('auditRequest',`${person(r.person).name} · ${t(r.type)} · ${r.start} → ${r.end}`);persist();closeModal();view='timeoff';requestTab='mine';requestStatus='all';requestType='all';render();toast(t('submitted'))};
requestDetails=function(id,publicOnly=false){const r=state.requests.find(r=>r.id===id);if(!r)return;const p=person(r.person),privateView=!publicOnly||canManage()||r.person===actorId();if(!privateView&&r.status!=='approved')return;const g=state.bonuses.find(g=>g.id===r.grantId);showModal(t(publicOnly?'eventDetails':'requestDetails'),`<div class="selected-info">${av(p,'lg')}<div><h3>${esc(p.name)}</h3><p>${esc(p.job)}</p></div></div><div class="info-section"><b>${esc(t('dates'))}</b>${esc(range(r.start,r.end))}${r.unit==='hours'?` · ${esc(r.startTime)}–${esc(r.endTime)}`:''}</div>${privateView?`<div class="info-section"><b>${esc(t('type'))}</b><span class="event-type ${r.type}">${icon(typeIcon(r.type))}${esc(t(r.type))}</span>${g?`<small class="cell-sub">${esc(t(g.reason))} · +1 · ${esc(t('bonusSeparate'))}</small>`:''}</div><div class="info-section"><b>${esc(t('duration'))}</b>${esc(duration(r))} · ${esc(t('netDays'))}</div><div class="info-section"><b>${esc(t('status'))}</b><span class="tag ${r.status}">${esc(t(r.status))}</span>${r.decidedBy?`<small class="cell-sub">${esc(person(r.decidedBy).name)}</small>`:''}</div><div class="info-section"><b>${esc(t('requestNote'))}</b>${esc(r.note||t('noNote'))}</div>${r.decisionNote?`<div class="info-section"><b>${esc(t('approvalNote'))}</b>${esc(r.decisionNote)}</div>`:''}`:`<div class="privacy-card" style="padding:15px">${icon('shield')}<div><h3>${esc(t('privacyTitle'))}</h3><p>${esc(t('privateCalendarText'))}</p></div></div>`}`,`${privateView&&canManage()&&r.person!==actorId()&&r.status==='pending'?`${btn(t('approve'),'approve','primary','check',`data-id="${r.id}" type="button"`)}${btn(t('reject'),'reject','secondary','x',`data-id="${r.id}" type="button"`)}`:btn(t('close'),'close-modal','primary','','type="button"')}`)};
changeRequest=function(id,status){const r=state.requests.find(r=>r.id===id);if(!r)return;if(status==='cancelled'){if(r.person!==actorId()&&!canAdmin()){toast(t('notAllowed'));return}if(!['pending','approved'].includes(r.status))return;r.status='cancelled';r.decidedBy=actorId();r.decidedAt=new Date().toISOString();audit('auditDecision',`${person(r.person).name} · ${r.start} · cancelled`);persist();closeModal();render();toast(t('requestUpdated'));return}if(!canManage()){toast(t('notAllowed'));return}if(r.person===actorId()){toast(t('reviewSelf'));return}if(r.status!=='pending')return;
 const remaining=r.type==='bonus'?null:availableAllowance(r.person,r.type,Number(r.start.slice(0,4)),r.id)-amount(r,Number(r.start.slice(0,4)));
 showModal(t(status==='approved'?'approve':'reject'),`<div class="selected-info">${av(person(r.person),'lg')}<div><h3>${esc(person(r.person).name)}</h3><p>${esc(t(r.type))} · ${esc(range(r.start,r.end))}</p></div></div><div class="request-summary ${r.type==='bonus'?'bonus-request-summary':''}">${icon(typeIcon(r.type))}<span><b>${esc(duration(r))}</b> · ${esc(t('netDays'))}</span></div>${remaining!==null?`<p class="approval-balance ${remaining<0?'over-budget':''}">${esc(t('balanceAfter'))}: <b>${number(remaining)} ${esc(t(r.type==='personal'?'hours':'days'))}</b></p>`:''}${remaining!==null&&remaining<0?`<p class="form-warning">${esc(t('confirmOver'))}</p>`:''}<input type="hidden" name="id" value="${id}"><input type="hidden" name="status" value="${status}"><label class="field" style="margin-top:20px"><span>${esc(t(status==='rejected'?'rejectReason':'approvalNote'))}</span><textarea name="decisionNote" maxlength="250" ${status==='rejected'?'required':''}></textarea></label><p class="form-error" id="form-error" role="alert"></p>`,modalActions(t(status==='approved'?'approve':'reject')),'decision-form');
};
function submitDecision(form){const d=new FormData(form),r=state.requests.find(r=>r.id===d.get('id')),status=d.get('status'),note=String(d.get('decisionNote')||'').trim();if(!r||!canManage()||r.person===actorId()||r.status!=='pending'||!['approved','rejected'].includes(status)){toast(t('notAllowed'));return}if(status==='rejected'&&!note){$('#form-error').textContent=t('rejectRequired');return}if(status==='approved'){const error=validateRequest(r,r.id);if(error){$('#form-error').textContent=error;return}}r.status=status;r.decidedBy=actorId();r.decidedAt=new Date().toISOString();r.decisionNote=note;audit('auditDecision',`${person(r.person).name} · ${r.start} · ${status}`);persist();closeModal();render();toast(t('decisionSaved'))}

function visibleRequests(){return state.requests.filter(r=>r.status==='approved'||calendarPending&&r.status==='pending'&&(canManage()||r.person===actorId()))}
function calendarEvents(date,personId){if(!isWorkingDate(date))return [];return visibleRequests().filter(r=>r.start<=date&&r.end>=date&&(!personId||r.person===personId))}
function eventType(r){return canManage()||r.person===actorId()||r.type==='bonus'?r.type:'publicAway'}
function calendarLegend(){const types=canManage()?['vacation','sick','personal','bonus']:['publicAway','bonus'];return `<div class="hr-legend">${types.map(type=>`<span><i class="legend-box ${type}">${icon(typeIcon(type))}</i>${esc(t(type))}</span>`).join('')}<span><i class="legend-box closure">${icon('calendar')}</i>${esc(t('companyClosed'))}</span><span><i class="legend-box weekend"></i>${esc(t('weekend'))}</span>${calendarPending?`<span><i class="legend-box pending"></i>${esc(t('pendingLegend'))}</span>`:''}</div>`}
renderCalendar=function(){const first=new Date(month.getFullYear(),month.getMonth(),1,12);return `${pageHeading('PEOPLE & PLANNING',t('calendar'),t('calendarSub'),btn(t('request'),'request','primary','plus'))}<section class="card calendar-card"><div class="calendar-toolbar"><div class="month-switch"><button class="icon-btn" data-action="month-prev" aria-label="${esc(t('monthBack'))}">${icon('left')}</button><h2>${esc(first.toLocaleDateString(locale(),{month:'long',year:'numeric'}))}</h2><button class="icon-btn" data-action="month-next" aria-label="${esc(t('monthNext'))}">${icon('right')}</button><button class="text-button" data-action="month-today">${esc(t('today'))}</button></div><div class="calendar-controls"><div class="segmented"><button data-action="calendar-mode" data-mode="team" class="${calendarMode==='team'?'selected':''}">${esc(t('calendarTeam'))}</button><button data-action="calendar-mode" data-mode="month" class="${calendarMode==='month'?'selected':''}">${esc(t('calendarMonth'))}</button></div><select class="filter-select" id="calendar-dept" aria-label="${esc(t('allDepartments'))}">${departmentOptions(department)}</select></div></div><div class="calendar-subtoolbar"><label class="pending-switch"><input type="checkbox" id="calendar-pending" ${calendarPending?'checked':''}>${esc(t('showPending'))}</label><button class="text-button" data-action="export-outlook">${icon('download')}${esc(t('outlookExport'))} (.ics)</button></div>${calendarMode==='team'?teamCalendar(first):monthCalendar(first)}<div class="calendar-bottom">${calendarLegend()}<p>${esc(t('calendarPrivacy'))}</p></div></section><div class="calendar-below"><div class="privacy-card">${icon('gift')}<div><h3>${esc(t('bonusBalance'))}</h3><p>${esc(t('bonusSeparate'))} ${esc(t('bonusDayNotTaken'))}</p>${canAdmin()?btn(t('grantBonus'),'grant-bonus','text-button','arrow'):''}</div></div><div class="privacy-card outlook-info">${icon('calendar')}<div><h3>Microsoft Outlook</h3><p>${esc(t('outlookNote'))}</p></div></div></div>`};
function teamCalendar(first){const n=new Date(first.getFullYear(),first.getMonth()+1,0).getDate();const dates=Array.from({length:n},(_,i)=>iso(new Date(first.getFullYear(),first.getMonth(),i+1,12)));const ps=activePeople().filter(p=>department==='all'||p.dept===department);return `<div class="roster-scroll" tabindex="0" aria-label="${esc(t('calendarTeam'))}"><table class="roster-table"><thead><tr><th class="roster-name">${esc(t('employee'))}<small>${esc(first.toLocaleDateString(locale(),{month:'short',year:'numeric'}))}</small></th>${dates.map(d=>`<th class="${d===TODAY?'today':''} ${[0,6].includes(toDate(d).getDay())?'weekend':''}"><span>${esc(fmt(d,{weekday:'short'}))}</span><b>${toDate(d).getDate()}</b></th>`).join('')}</tr></thead><tbody>${ps.map(p=>`<tr><th scope="row" class="roster-name"><div class="table-person">${av(p,'sm')}<div><b>${esc(p.name)}</b><small>${esc(t(p.dept))}</small></div></div></th>${dates.map(d=>{const h=companyClosure(d),rs=calendarEvents(d,p.id),weekend=[0,6].includes(toDate(d).getDay());return `<td class="${weekend?'weekend':''} ${d===TODAY?'today':''}">${h?`<button class="roster-event closure" data-action="closure-detail" data-id="${h.id}" aria-label="${esc(t('companyClosed'))} · ${esc(h.nameKey?t(h.nameKey):h.title)} · ${esc(fmt(d))}">${icon('calendar')}</button>`:rs.length?rs.map(r=>`<button class="roster-event ${eventType(r)} ${r.status==='pending'?'pending-event':''} ${r.unit==='hours'?'partial':''}" data-action="calendar-event" data-id="${r.id}" aria-label="${esc(p.name)} · ${esc(t(eventType(r)))} · ${esc(fmt(d))}" title="${esc(t(eventType(r)))}${r.unit==='hours'?' · '+esc(duration(r)):''}">${icon(typeIcon(eventType(r)))}</button>`).join(''):`<span class="empty-roster-day">${toDate(d).getDate()}</span>`}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
function monthCalendar(first){const begin=startWeek(iso(first)),n=Math.ceil(((first.getDay()+6)%7+new Date(first.getFullYear(),first.getMonth()+1,0).getDate())/7)*7;return `<div class="calendar-days">${Array.from({length:7},(_,i)=>`<div>${esc(fmt(addDays('2026-11-02',i),{weekday:'short'}))}</div>`).join('')}</div><div class="calendar-grid">${Array.from({length:n},(_,i)=>{const d=addDays(begin,i),date=toDate(d),h=companyClosure(d);return `<div class="calendar-cell ${date.getMonth()!==first.getMonth()?'other':''} ${[0,6].includes(date.getDay())?'weekend':''} ${d===TODAY?'today':''}"><div class="day-number"><span>${date.getDate()}</span></div>${h?`<button class="calendar-event closure" data-action="closure-detail" data-id="${h.id}">${icon('calendar')}${esc(t('companyClosed'))}</button>`:calendarEvents(d).filter(r=>department==='all'||person(r.person).dept===department).map(r=>`<button class="calendar-event ${eventType(r)} ${r.status==='pending'?'pending-event':''}" data-action="calendar-event" data-id="${r.id}" title="${esc(person(r.person).name)} · ${esc(t(eventType(r)))}">${r.type==='bonus'?icon('gift'):''}${esc(person(r.person).name.split(' ')[0])} · ${esc(t(eventType(r)))}</button>`).join('')}</div>`}).join('')}</div>`}
function closureDetails(id){const h=state.holidays.find(h=>h.id===id);if(!h)return;showModal(t('companyClosed'),`<div class="closure-detail-symbol">${icon('calendar')}</div><div class="info-section"><b>${esc(h.nameKey?t(h.nameKey):h.title)}</b>${esc(range(h.start,h.end))}</div><p class="modal-subtitle">${esc(t('closureNote'))}</p>`,`${canAdmin()?btn(t('editHoliday'),'edit-holiday','secondary','edit',`data-id="${h.id}" type="button"`):''}${btn(t('close'),'close-modal','primary','','type="button"')}`)}

function utcForWorkTime(date,time){
 const [y,m,d]=date.split('-').map(Number),[hour,minute]=time.split(':').map(Number),target=Date.UTC(y,m-1,d,hour,minute);let candidate=target;
 const formatter=new Intl.DateTimeFormat('en-US',{timeZone:'America/Edmonton',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
 for(let i=0;i<3;i++){const parts=Object.fromEntries(formatter.formatToParts(new Date(candidate)).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));candidate+=target-Date.UTC(parts.year,parts.month-1,parts.day,parts.hour,parts.minute,parts.second)}
 return new Date(candidate).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');
}
function buildOutlookCalendar(year){
 const dt=d=>d.replace(/-/g,''),stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');
 const escapeICS=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
 const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//KEL Connect//Company Calendar Demo//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:KEL Connect'];
 let count=0;
 function event(id,start,end,title,startTime='',endTime=''){count++;lines.push('BEGIN:VEVENT',`UID:${id}@kel-connect.demo`,`DTSTAMP:${stamp}`,startTime?`DTSTART:${utcForWorkTime(start,startTime)}`:`DTSTART;VALUE=DATE:${dt(start)}`,endTime?`DTEND:${utcForWorkTime(end,endTime)}`:`DTEND;VALUE=DATE:${dt(addDays(end,1))}`,`SUMMARY:${escapeICS(title)}`,'TRANSP:OPAQUE','END:VEVENT')}
 const startYear=`${year}-01-01`,endYear=`${year}-12-31`;
 for(const h of state.holidays.filter(h=>h.active!==false&&h.start<=endYear&&h.end>=startYear))event('closure-'+h.id,h.start<startYear?startYear:h.start,h.end>endYear?endYear:h.end,t('companyClosed')+' · '+(h.nameKey?t(h.nameKey):h.title));
 for(const r of state.requests.filter(r=>r.status==='approved'&&r.start<=endYear&&r.end>=startYear&&person(r.person).active!==false&&(department==='all'||person(r.person).dept===department))){
  const s=r.start<startYear?startYear:r.start,e=r.end>endYear?endYear:r.end;
  // Export each working day separately, so closures/weekends are never marked as leave.
  for(let d=s;d<=e;d=addDays(d,1)){if(isWorkingDate(d))event(r.id+'-'+d,d,d,`${person(r.person).name} · ${t(r.type==='bonus'?'bonus':'publicAway')}`,r.unit==='hours'?r.startTime:'',r.unit==='hours'?r.endTime:'')}
 }
 lines.push('END:VCALENDAR');
 function fold(line){const pieces=[];let part='';for(const ch of line){if(new TextEncoder().encode(part+ch).length>75){pieces.push(part);part=' '+ch}else part+=ch}pieces.push(part);return pieces.join('\r\n')}
 return {count,text:lines.map(fold).join('\r\n')+'\r\n'};
}
function exportOutlook(){const year=month.getFullYear(),result=buildOutlookCalendar(year);if(!result.count){toast(t('exportEmpty'));return}const blob=new Blob([result.text],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`KEL-Connect-${year}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('exported'))}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 if(a==='admin-tab'){const allowed=canAdmin()?['users','requests','holidays','bonus','settings','history']:['requests','history'];if(!canManage()||!allowed.includes(b.dataset.tab)){toast(t('notAllowed'));return}adminTab=b.dataset.tab;render()}
 else if(a==='add-user')userForm();else if(a==='edit-user')userForm(id);else if(a==='toggle-user')toggleUser(id);
 else if(a==='add-holiday')holidayForm();else if(a==='edit-holiday')holidayForm(id);else if(a==='toggle-holiday')toggleHoliday(id);
 else if(a==='grant-bonus')grantForm();else if(a==='toggle-bonus')toggleBonus(id);else if(a==='request-bonus')requestModal('bonus');
 else if(a==='calendar-mode'){calendarMode=b.dataset.mode;render()}
 else if(a==='closure-detail')closureDetails(id);else if(a==='export-outlook')exportOutlook();
});
document.addEventListener('change',e=>{if(e.target.id==='demo-actor'){clearAttachmentQueue();const p=state.people.find(p=>p.id===e.target.value&&p.active);if(!p)return;state.demoActor=p.id;activeChat='general';requestTab='mine';messageSearch='';closeModal();persist();render()}else if(e.target.id==='request-status'){requestStatus=e.target.value;render()}else if(e.target.id==='request-type'){requestType=e.target.value;render()}else if(e.target.id==='calendar-pending'){calendarPending=e.target.checked;render()}});
document.addEventListener('input',e=>{if(e.target.id==='admin-people-search'){adminPeopleQuery=e.target.value;$('#admin-users-table').innerHTML=userRows()}});
document.addEventListener('submit',e=>{const form=e.target,formId=form.getAttribute('id');if(!['user-form','holiday-form','bonus-form','decision-form','settings-form'].includes(formId))return;e.preventDefault();if(formId==='user-form')submitUser(form);else if(formId==='holiday-form')submitHoliday(form);else if(formId==='bonus-form')submitGrant(form);else if(formId==='decision-form')submitDecision(form);else if(formId==='settings-form'&&canAdmin()){const h=Number(new FormData(form).get('hoursPerDay'));if(!Number.isFinite(h)||h<1||h>24){$('#settings-error').textContent=t('badHours');return}state.settings.hoursPerDay=h;audit('auditSettings',`${h} h / day`);persist();render();toast(t('settingsSaved'))}});

initializeHR();
render();
